class ToastrService{constructor($mdToast){this.$mdToast=$mdToast}showErrorToast(errorMessage){if(!errorMessage){errorMessage="An unexpected error occurred. Please try again"}console.log("Error:",errorMessage);this.showToast("Oops an unexpected error occured. Please try again or contact support.","error")}showSuccessToast(successMessage){console.log("Success:",successMessage);this.showToast(successMessage,"success")}showWarningToast(warningMessage){console.log("Warning:",warningMessage);this.showToast(warningMessage,"warning")}showToast(message,theme){this.$mdToast.show(this.$mdToast.simple().textContent(message).position("top right").hideDelay(1e4).theme(theme+"-toast"))}}angular.module("uDispatch").service("toastrService",ToastrService);